def find_pairs(N):
    pairs = []
    # We only need to check odd primes, as p+r=800 (even)
    # If p=2, r=798 (not prime).
    limit = N // 2
    for p in range(3, limit + 1):
        if is_prime(p):
            r = N - p
            if is_prime(r):
                # Ensure p < r (this is automatically true if p <= N/2 and p != N/2)
                if p < r:
                    pairs.append((p, r))
    return pairs

